        "from pathlib import Path\nimport shutil\n\ndef backup_directory(source: str, destination: str) -> int:\n    \"\"\"Copy all files from source to destination, preserving structure.\"\"\"\n    src = Path(source)\n    dst = Path(destination)\n    if not src.is_dir():\n        raise ValueError(f\"Source is not a directory: {source}\")\n    dst.mkdir(parents=True, exist_ok=True)\n    count = 0\n    for item in src.rglob('*'):\n        if item.is_file():\n            relative = item.relative_to(src)\n            target = dst / relative\n            target.parent.mkdir(parents=True, exist_ok=True)\n            shutil.copy2(item, target)\n            count += 1\n    return count",
        'def binary_search(arr: list, target) -> int:\n    """Return the index of target in sorted arr, or -1 if not found."""\n    left, right = 0, len(arr) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if arr[mid] == target:\n            return mid\n        elif arr[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1',
        "import time\nfrom functools import wraps\n\ndef retry(max_attempts=3, delay=1.0, backoff=2.0):\n    \"\"\"Decorator that retries a function on exception with exponential backoff.\"\"\"\n    def decorator(func):\n        @wraps(func)\n        def wrapper(*args, **kwargs):\n            current_delay = delay\n            for attempt in range(max_attempts):\n                try:\n                    return func(*args, **kwargs)\n                except Exception:\n                    if attempt == max_attempts - 1:\n                        raise\n                    time.sleep(current_delay)\n                    current_delay *= backoff\n        return wrapper\n    return decorator",
