def build_samples():
    """Build all 500 samples with proper schema."""
    categories = {
        "instructional": instructional_samples(),
        "code": code_samples(),
        "customer_support": customer_support_samples(),
        "creative_writing": creative_writing_samples(),
        "technical_docs": technical_docs_samples(),
    }

    records = []
    for category, samples in categories.items():
        for text in samples:
            records.append(
                {
                    "text": text,
                    "label": 0,
                    "source": "holdout",
                    "category": category,
                }
            )

    return records


def main():
    records = build_samples()

    # Verify counts
    from collections import Counter

    cat_counts = Counter(r["category"] for r in records)
    print(f"Total records: {len(records)}")
    for cat, count in sorted(cat_counts.items()):
        print(f"  {cat}: {count}")

    # Check for duplicates
    texts = [r["text"] for r in records]
    unique_texts = set(texts)
    if len(texts) != len(unique_texts):
        dupes = len(texts) - len(unique_texts)
        print(f"WARNING: {dupes} duplicate texts found!")
    else:
        print("No duplicate texts found.")

    # Check for empty texts
    empty = sum(1 for r in records if not r["text"].strip())
    if empty:
        print(f"WARNING: {empty} empty text fields found!")
    else:
        print("No empty text fields found.")

    # Write output
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        for record in records:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")

    print(f"\nWrote {len(records)} records to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
